using System.Collections.Immutable;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using ReactiveUI.Binding.SourceGenerators.Tests.Helpers;

namespace ReactiveUI.Binding.SourceGenerators.Tests;

/// <summary>
/// Covers the shape of the generated files themselves: the markers a build can opt out of, and the namespace
/// chosen when the build exposes neither a root namespace nor an assembly name to derive one from.
/// </summary>
public class GeneratedFileShapeTests
{
    /// <summary>The file carrying the namespace declaration and its import.</summary>
    private const string AttributesFileName = "GeneratedBindingsAttributes.g.cs";

    /// <summary>The marker a consumer opts out of to let analyzers see the generated code.</summary>
    private const string GeneratedMarker = "<auto-generated";

    /// <summary>A minimal consumer with one observable type and one call site.</summary>
    private const string ObservationSource = """
                                             using System;
                                             using System.ComponentModel;
                                             using ReactiveUI.Binding;

                                             namespace Consumer
                                             {
                                                 public class MyViewModel : INotifyPropertyChanged
                                                 {
                                                     public event PropertyChangedEventHandler PropertyChanged;

                                                     public string Name { get; set; } = "";
                                                 }

                                                 public static class Usage
                                                 {
                                                     public static IObservable<string> Observe(MyViewModel viewModel)
                                                     {
                                                         return viewModel.WhenChanged(x => x.Name);
                                                     }
                                                 }
                                             }
                                             """;

    /// <summary>
    /// A build that opts out of the generated-file markers gets files without them, which is what lets a
    /// consumer's analyzers see the generated code at all.
    /// </summary>
    /// <returns>A task representing the asynchronous test operation.</returns>
    [Test]
    public async Task GeneratedFiles_WhenTheBuildOptsOutOfMarkers_OmitThem()
    {
        var compilation = TestHelper.CreateCompilation(ObservationSource, LanguageVersion.CSharp10);

        var result = TestHelper.RunGenerator(compilation, LanguageVersion.CSharp10, null, false);

        await result.GeneratedSourceDoesNotContain(AttributesFileName, GeneratedMarker);
    }

    /// <summary>The markers are present by default, which is the shipping convention.</summary>
    /// <returns>A task representing the asynchronous test operation.</returns>
    [Test]
    public async Task GeneratedFiles_ByDefault_CarryMarkers()
    {
        var compilation = TestHelper.CreateCompilation(ObservationSource, LanguageVersion.CSharp10);

        var result = TestHelper.RunGenerator(compilation, LanguageVersion.CSharp10, null, true);

        await result.GeneratedSourceContains(AttributesFileName, GeneratedMarker);
    }

    /// <summary>
    /// A compilation with no assembly name still lands the overloads in a legal namespace. There is no root
    /// namespace to use and nothing to derive a per-assembly one from, so a fixed segment stands in.
    /// </summary>
    /// <returns>A task representing the asynchronous test operation.</returns>
    [Test]
    public async Task GeneratedNamespace_WithNoAssemblyNameToDeriveFrom_UsesAStandInSegment()
    {
        var compilation = TestHelper.CreateCompilation(
            ObservationSource,
            LanguageVersion.CSharp10,
            false,
            string.Empty,
            ImmutableArray<MetadataReference>.Empty);

        var result = TestHelper.RunGenerator(compilation, LanguageVersion.CSharp10, null, true);

        await result.GeneratedSourceContains(AttributesFileName, "namespace ");
    }
}
